import {modules,imageAssets,labExperiments,references} from './data.js';

const $=id=>document.getElementById(id);
const safe=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').trim();
const shuffle=arr=>{let a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const mod=id=>modules.find(m=>m.id===id)||modules[0];
const persistKey='humanbody.atlas.v1';
const startData={studied:{},attempts:[],exams:[],cards:{},associations:{},pao:[],bookmarks:[],reduceMotion:false,seen:{}};
let progress;try{progress={...startData,...JSON.parse(localStorage.getItem(persistKey)||'{}')};}catch{progress={...startData};}
function store(){try{localStorage.setItem(persistKey,JSON.stringify(progress));}catch{notify('Armazenamento não disponível neste navegador.');}}
const state={view:'inicio',module:'digestorio',atlas:'body',atlasZoom:1,atlasLabels:true,lab:0,labStep:0,labRunning:false,labSpeed:1,labParam:'normal',quiz:null,quizAnswer:null,quizType:'multipla',quizModule:'todos',quizDifficulty:'todos',quizQuantity:10,quizReview: false,quizExam:false,quizTimer:true,quizStyle:'classico',quizStartedAt:0,flashModule:'todos',flashIndex:0,flashFlipped:false,memoryModule:'digestorio',memoryIndex:0,memoryReveal:true,mapModule:'todos',search:'',tutorQuery:'',tutorResults:null,modal:null,sidebarOpen:false};
let labTimer=null,quizTicker=null;
const routes=['inicio','sistemas','atlas','laboratorio','treinamento','simulados','memorizacao','flashcards','mapas','evolucao','biblioteca','tutor'];
function I(name,size=19){const p={home:'<path d="m3 9 9-7 9 7v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/>',layers:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',atom:'<ellipse cx="12" cy="12" rx="10" ry="4.4"/><ellipse cx="12" cy="12" rx="10" ry="4.4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4.4" transform="rotate(120 12 12)"/><circle cx="12" cy="12" r="1.5" fill="currentColor"/>',flask:'<path d="M9 3h6M10 3v7l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3"/><path d="M7 16h10"/>',list:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',brain:'<path d="M12 18V5a3 3 0 0 0-5.5-1.7A4 4 0 0 0 3 9a4 4 0 0 0 0 7 4 4 0 0 0 5 4 3.5 3.5 0 0 0 4-2Zm0 0V5a3 3 0 0 1 5.5-1.7A4 4 0 0 1 21 9a4 4 0 0 1 0 7 4 4 0 0 1-5 4 3.5 3.5 0 0 1-4-2Z"/>',cards:'<rect x="7" y="3" width="14" height="18" rx="2"/><path d="M5 7H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h10"/>',network:'<circle cx="12" cy="4" r="2"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/><path d="M11 6 6 17M13 6l5 11M7 19h10"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 5-8"/>',book:'<path d="M12 7a8 8 0 0 0-9-2v15a8 8 0 0 1 9 2 8 8 0 0 1 9-2V5a8 8 0 0 0-9 2Z"/><path d="M12 7v15"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.8-5.4a9 9 0 0 1-.8-4.1 8.5 8.5 0 0 1 17 0Z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',chevron:'<path d="m9 18 6-6-6-6"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',check:'<path d="m4 12 5 5L20 6"/>',play:'<path d="m8 5 12 7-12 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M3 11a9 9 0 1 1 2.5 6.5M3 4v7h7"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',star:'<path d="m12 2 3.1 6.3 6.9 1-5 4.8 1.2 6.9L12 17.8 5.8 21l1.2-6.9-5-4.8 6.9-1Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.7 9a2.5 2.5 0 0 1 4.6 1c0 2-2.3 2.3-2.3 4M12 17h.01"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m3 17 5-5 4 4 3-3 6 6"/>',external:'<path d="M15 4h5v5M20 4l-9 9"/><path d="M19 13v7H4V5h7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="#160709"/><circle cx="15" cy="17" r="2" fill="#160709"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.atom}</svg>`;}
const titles={inicio:'Início',sistemas:'Sistemas',atlas:'Atlas',laboratorio:'Laboratório',treinamento:'Treinamento',simulados:'Simulados',memorizacao:'Memorização',flashcards:'Flashcards',mapas:'Mapas mentais',evolucao:'Evolução',biblioteca:'Biblioteca',tutor:'Tutor'};
const navIcons={inicio:'home',sistemas:'layers',atlas:'heart',laboratorio:'flask',treinamento:'target',simulados:'list',memorizacao:'brain',flashcards:'cards',mapas:'network',evolucao:'chart',biblioteca:'book',tutor:'chat'};
const imageCdn={"body": "https://upload.wikimedia.org/wikipedia/commons/0/00/202403_human_anatomy_organs.svg", "internal": "https://upload.wikimedia.org/wikipedia/commons/e/e3/Internal_organs.svg", "digestive": "https://upload.wikimedia.org/wikipedia/commons/c/c5/Digestive_system_diagram_en.svg", "respiratory": "https://upload.wikimedia.org/wikipedia/commons/5/5e/Respiratory_system_complete_en.svg", "heart": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Heart_diagram_%28en%29.svg", "urinary": "https://upload.wikimedia.org/wikipedia/commons/3/30/Urinary_system.svg", "endocrine": "https://upload.wikimedia.org/wikipedia/commons/0/09/Endocrine_System.svg", "vascular": "https://upload.wikimedia.org/wikipedia/commons/e/e3/Internal_organs.svg", "alveoli": "https://upload.wikimedia.org/wikipedia/commons/8/86/Alveolus_diagram-pt.svg", "circulation": "https://upload.wikimedia.org/wikipedia/commons/a/ac/Arterial_vs_Venous_Systems.svg", "vesselCompare": "https://upload.wikimedia.org/wikipedia/commons/6/60/Artery_Vein_Capillary_Comparison.png", "hormones": "https://upload.wikimedia.org/wikipedia/commons/d/d5/Endocrine_glands.png", "pituitary": "https://upload.wikimedia.org/wikipedia/commons/8/85/Pituitary_Gland.png", "thyroid": "https://upload.wikimedia.org/wikipedia/commons/b/b5/Thyroid_gland_%26_thyroid_cartilage.svg", "gonads": "https://upload.wikimedia.org/wikipedia/commons/9/92/Male_and_female_genital_organs.svg", "pancreas": "https://upload.wikimedia.org/wikipedia/commons/f/fe/Human_Pancreas_%28NIH_BioArt_239%29.svg"};
function imgUrl(key){return imageCdn[key]||imageCdn.body;}
function sourceLink(key,label='Créditos e licença'){let s=imageAssets[key]||imageAssets.body;return `<a class="source-link" target="_blank" rel="noopener noreferrer" href="${safe(s.source)}">${I('external',13)} ${safe(label)} · ${safe(s.creator)}</a>`;}
function scienceImage(key,{cls='',alt='',fit='contain',onClick=true}={}){let a=imageAssets[key]||imageAssets.body;return `<div class="scientific-image ${cls}" data-image="${safe(key)}" style="--fit:${fit}"><img src="${imgUrl(key)}" alt="${safe(alt||a.description)}" loading="lazy" referrerpolicy="no-referrer" data-img="${safe(key)}"><div class="img-fallback" hidden>${I('image',34)}<strong>${safe(a.description)}</strong><small>Imagem indisponível nesta conexão</small><a href="${safe(a.source)}" target="_blank" rel="noopener noreferrer">Abrir na Wikimedia Commons ${I('external',13)}</a></div>${onClick?`<button class="zoom-img" data-action="image-modal" data-key="${safe(key)}" aria-label="Ampliar imagem">${I('plus',16)}</button>`:''}</div>`;}
function notify(msg){const box=$('toast');if(!box)return;box.textContent=msg;box.classList.add('show');setTimeout(()=>box.classList.remove('show'),2800);}
const countQuestions=modules.reduce((n,m)=>n+m.facts.length,0);
function counts(){let a=progress.attempts||[];return {studied:Object.values(progress.studied||{}).filter(Boolean).length,answered:a.length,correct:a.filter(x=>x.ok).length,accuracy:a.length?Math.round(a.filter(x=>x.ok).length/a.length*100):0,exams:(progress.exams||[]).length,flash:Object.keys(progress.cards||{}).length};}
function btn(text,action,{cls='btn-primary',attrs='',icon=''}={}){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${icon?I(icon,16):''}${safe(text)}</button>`;}
function badge(text){return `<span class="micro-tag">${safe(text)}</span>`;}
function sectionTitle(kicker,title,desc=''){return `<div class="section-heading"><div><div class="eyebrow">${safe(kicker)}</div><h2>${safe(title)}</h2>${desc?`<p>${safe(desc)}</p>`:''}</div></div>`;}
function frame(content,selected){let c=counts();return `<div class="site-shell"><header class="masthead"><div class="masthead-top"><span class="masthead-micro">LABORATÓRIO DE ANATOMIA E FISIOLOGIA</span><button class="mobile-menu" data-action="toggle-menu" aria-label="Abrir navegação">${I('menu',22)}</button><div class="brand" data-go="inicio"><span class="brand-mark">${I('heart',35)}</span><div><strong>HUMAN <em>BODY</em></strong><span>ATLAS DA VIDA <i>•</i> RESEARCH</span></div></div><span class="masthead-status"><span class="live-dot"></span> EXPLORAÇÃO CIENTÍFICA</span></div><nav class="navigation ${state.sidebarOpen?'nav-open':''}" aria-label="Navegação principal">${routes.map(r=>`<button class="nav-link ${selected===r?'active':''}" data-go="${r}">${I(navIcons[r],16)}<span>${titles[r].toUpperCase()}</span></button>`).join('')}</nav><div class="pulse-line"></div></header><div class="site-content">${content}</div><footer class="footer"><div class="footer-head"><span class="footer-brand">HUMAN <em>BODY</em></span><span>Conhecimento que circula.</span></div><div class="footer-links"><button data-go="inicio">Início</button><button data-go="sistemas">Sistemas</button><button data-go="laboratorio">Laboratório</button><button data-go="biblioteca">Créditos & fontes</button><button data-action="toggle-motion">${progress.reduceMotion?'Ativar movimentos':'Reduzir movimentos'}</button></div><small>Atlas educacional • ${modules.length} módulos • ${countQuestions} conceitos e questões estruturadas • Registro local no navegador • Não substitui orientação médica</small></footer></div>`;}
function home(){const c=counts();let chosen=[modules[3],modules[4],modules[8]];return `<div class="home-layout"><main class="home-main"><section class="hero-panel"><div class="hero-content"><div class="eyebrow line">PLATAFORMA DE ESTUDO / VERSÃO INTERATIVA</div><h1>EXPLORANDO O <span>MISTÉRIO</span> DO CORPO HUMANO.</h1><p>BIOLOGIA, CIÊNCIA E INOVAÇÃO. Descubra como os sistemas do organismo trabalham juntos.</p><div class="hero-actions">${btn('Explorar sistemas','navigate',{icon:'arrow',attrs:'data-view="sistemas"'})}${btn('Treinar conhecimento','navigate',{cls:'btn-outline',attrs:'data-view="treinamento"',icon:'target'})}</div><div class="hero-stats"><span><strong>13</strong> SISTEMAS</span><span><strong>${countQuestions}</strong> QUESTÕES</span><span><strong>13</strong> EXPERIMENTOS</span></div></div><div class="hero-visual"><div class="hero-halo"></div>${scienceImage('body',{cls:'hero-body',alt:'Ilustração científica de órgãos humanos'})}<div class="hero-redlines"></div></div></section><div class="mini-rule"><span>ÁREAS DE INVESTIGAÇÃO</span><span>01 / 13</span></div><div class="feature-grid">${chosen.map((m,i)=>`<article class="feature-card" style="--c:${m.color}"><div class="feature-top"><span class="feature-icon">${I(i===0?'heart':i===1?'atom':'network',25)}</span><span class="feature-index">0${i+1}</span></div><h3>${safe(i===0?'Pesquisa Vascular':i===1?'Diagnóstico Hemático':'Bioengenharia Tecidual')}</h3><p>${safe(m.summary)}</p><button class="small-pill" data-action="open-module" data-id="${m.id}">Ler mais ${I('arrow',13)}</button></article>`).join('')}</div><section class="intro-copy"><div class="eyebrow">CIÊNCIA EM PROFUNDIDADE</div><h2>Pesquisa Anatômica Avançada</h2><p>Explore a organização do organismo, examine ilustrações anatômicas com créditos, acompanhe modelos fisiológicos e teste sua compreensão. O estudo é organizado por estruturas, mecanismos, relações e revisão.</p><p>Todos os exercícios se baseiam em fatos disponíveis nas aulas; seus acertos e revisões ficam armazenados apenas neste navegador.</p></section><div class="home-divider"></div>${sectionTitle('SEU PAINEL','Continue a exploração','Clique em um sistema para aprofundar seus conhecimentos.')}<div class="quick-grid">${modules.map((m,i)=>`<button class="quick-module" data-action="open-module" data-id="${m.id}" style="--c:${m.color}"><span class="quick-num">${String(i+1).padStart(2,'0')}</span><span class="quick-label"><b>${safe(m.name)}</b><small>${safe(m.short)}</small></span>${progress.studied[m.id]?I('check',17):I('chevron',17)}</button>`).join('')}</div></main><aside class="rightbar"><div class="right-group"><h3>ÚLTIMAS DESCOBERTAS</h3><div class="right-story" data-action="open-module" data-id="cardiovascular"><b>Pesquisa Hematológica</b><span>Como o sangue sustenta a vida</span></div><div class="right-story" data-action="open-module" data-id="hormonios"><b>Bioengenharia Tecidual</b><span>Sinais químicos e respostas celulares</span></div></div><div class="right-group"><h3>EVENTOS DE ESTUDO</h3><button class="red-text-link" data-go="laboratorio">Experimentos virtuais interativos</button><button class="red-text-link" data-go="simulados">Desafio de fisiologia integrada</button><button class="red-text-link" data-go="memorizacao">Treino do palácio anatômico</button></div><div class="right-group"><h3>BUSCAR</h3>${searchBox('side-search')}</div><div class="right-group sidebar-progress"><h3>SEU PROGRESSO</h3><div class="big-percent">${c.accuracy}<span>%</span></div><p>Precisão das questões respondidas</p><div class="progress-bar"><i style="width:${c.accuracy}%"></i></div><div class="side-stats"><span>${c.studied}/13 módulos</span><span>${c.answered} respostas</span></div><button class="sidebar-button" data-go="evolucao">Ver relatório ${I('arrow',13)}</button></div><div class="right-group"><h3>IMAGEM CIENTÍFICA</h3>${scienceImage('internal',{cls:'sidebar-image'})}${sourceLink('internal','Fonte da ilustração')}</div></aside></div>`;}
function searchBox(id='site-search'){return `<form class="search-form" data-searchform="1"><input id="${id}" type="search" name="query" aria-label="Buscar estruturas e conceitos" placeholder="Buscar órgão, hormônio..." value="${safe(state.search)}"><button aria-label="Pesquisar" type="submit">${I('search',17)}</button></form>`;}
function moduleCard(m,i){const studied=progress.studied[m.id];return `<article class="module-card" style="--c:${m.color}"><button class="module-card-hit" data-action="open-module" data-id="${m.id}" aria-label="Estudar ${safe(m.name)}"><div class="module-card-top"><span class="module-id">MÓDULO ${String(i+1).padStart(2,'0')}</span><span>${studied?`<span class="done-tag">${I('check',13)} ESTUDADO</span>`:I('arrow',18)}</span></div><div class="card-image">${scienceImage(m.image,{onClick:false})}</div><h3>${safe(m.name)}</h3><p>${safe(m.summary)}</p><div class="module-bottom"><span>${m.facts.length} conceitos</span><span>Explorar ${I('chevron',14)}</span></div></button></article>`;}
function modulesView(){return `<div class="page-intro"><div>${badge('13 SISTEMAS COMPLETOS')}<h1>Biblioteca dos <em>Sistemas Humanos</em></h1><p>Aprenda cada órgão, entenda seu funcionamento e conecte os conhecimentos a fenômenos de outros sistemas.</p></div><div class="page-illustration">${I('atom',72)}</div></div><div class="toolbar"><span>${modules.length} trilhas anatômicas · ${countQuestions} fatos científicos</span>${btn('Treinamento misto','navigate',{cls:'btn-outline',attrs:'data-view="treinamento"',icon:'target'})}</div><div class="modules-grid">${modules.map(moduleCard).join('')}</div>`;}
function moduleView(){let m=mod(state.module),index=modules.indexOf(m),steps=m.steps;return `<div class="breadcrumbs"><button data-go="sistemas">SISTEMAS</button>${I('chevron',14)}<span>MÓDULO ${String(index+1).padStart(2,'0')}</span></div><section class="lesson-top" style="--c:${m.color}"><div class="lesson-top-copy"><div class="eyebrow">${safe(m.tag)} / AULA ${String(index+1).padStart(2,'0')}</div><h1>${safe(m.name)}</h1><p>${safe(m.summary)}</p><div class="lesson-buttons">${btn(progress.studied[m.id]?'Marcar como não estudado':'Marcar como estudado','toggle-studied',{icon:'check'})}${btn('Treinar este sistema','train-module',{cls:'btn-outline',icon:'target'})}</div></div>${scienceImage(m.image,{cls:'lesson-hero-image'})}</section><div class="lesson-layout"><aside class="lesson-nav"><div class="eyebrow">ROTEIRO DE APRENDIZAGEM</div>${['Visão geral','Atlas visual','Anatomia e termos','Fisiologia e percurso','Conexões e aplicação'].map((a,i)=>`<a href="#lesson-${i}" class="lesson-anchor"><span>${String(i+1).padStart(2,'0')}</span>${a}</a>`).join('')}<div class="lesson-side-foot">${I('book',18)}<span>${m.facts.length} conceitos essenciais</span></div></aside><div class="lesson-articles"><article class="article" id="lesson-0">${sectionTitle('01 — OBSERVAÇÃO','Compreenda o sistema',m.focus)}<p class="lead-text">${safe(m.summary)} Seu estudo deve conectar <strong>localização anatômica, estrutura e função</strong>. Utilize o percurso abaixo para memorizar a ordem dos fenômenos.</p><div class="lesson-info">${I('info',19)}<span>Conteúdo conceitual educativo. Os modelos animados são simplificações fisiológicas, não reproduções clínicas em tempo real.</span></div></article><article class="article" id="lesson-1">${sectionTitle('02 — ATLAS','Visualização anatômica','Ilustração científica real hospedada pela Wikimedia Commons.')}<div class="atlas-inline">${scienceImage(m.image,{cls:'atlas-big'})}<div class="atlas-legend"><h3>${safe(m.name)}</h3><p>Amplie a imagem para observar sua organização. Consulte a fonte original para conferir nomenclaturas presentes na arte e condições de reutilização.</p>${sourceLink(m.image)}<button class="btn btn-outline" data-action="atlas-for-module">${I('image',17)} Abrir no Atlas</button></div></div></article><article class="article" id="lesson-2">${sectionTitle('03 — ANATOMIA','Estruturas e conceitos','Toque em uma linha para expandir a explicação.')}<div class="fact-accordion">${m.facts.map((f,i)=>`<details class="fact-entry" ${i===0?'open':''}><summary><span class="fact-no">${String(i+1).padStart(2,'0')}</span><strong>${safe(f.term)}</strong>${I('plus',15)}</summary><p>${safe(f.def)}</p></details>`).join('')}</div></article><article class="article" id="lesson-3">${sectionTitle('04 — FISIOLOGIA','Acompanhe o processo','Sequência didática, uma etapa por vez.')}<ol class="process-steps">${steps.map((st,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${safe(st)}</p></li>`).join('')}</ol><div class="inline-cta">${I('flask',25)}<div><b>Experimente o mecanismo</b><small>Laboratório com controles de tempo e etapas</small></div><button data-action="lab-for-module">Abrir simulação ${I('arrow',15)}</button></div></article><article class="article" id="lesson-4">${sectionTitle('05 — CONEXÕES','Integração entre sistemas')}<div class="relation-grid">${m.relations.map(r=>`<div class="relation">${I('network',17)}<span>${safe(r)}</span></div>`).join('')}</div><div class="end-actions">${btn('Exercícios deste módulo','train-module',{icon:'target'})}${btn('Criar palácio de memória','memory-for-module',{cls:'btn-outline',icon:'brain'})}${btn('Revisar em flashcards','flash-for-module',{cls:'btn-outline',icon:'cards'})}</div></article></div></div>`;}
function atlas(){const assets=Object.entries(imageAssets);const a=imageAssets[state.atlas]||imageAssets.body;return `${sectionTitle('ACERVO ANATÔMICO','Atlas visual interativo','Ilustrações anatômicas reais em arquivos do Wikimedia Commons; os nomes das imagens podem estar em inglês.')}<div class="atlas-controls"><span>${I('image',18)} ${safe(a.description)}</span><div class="control-group"><button data-action="atlas-zoom-out" aria-label="Diminuir zoom">${I('minus',16)}</button><span>${Math.round(state.atlasZoom*100)}%</span><button data-action="atlas-zoom-in" aria-label="Aumentar zoom">${I('plus',16)}</button><button data-action="atlas-reset" aria-label="Reiniciar zoom">${I('reset',16)}</button><button data-action="atlas-labels">${I('eye',16)} ${state.atlasLabels?'Ocultar legenda':'Mostrar legenda'}</button></div></div><div class="atlas-workspace"><div class="atlas-board"><div class="atlas-canvas"><div class="atlas-image-wrap" style="--atlaszoom:${state.atlasZoom}">${scienceImage(state.atlas,{cls:'atlas-focus'})}</div></div></div><div class="atlas-inspector"><div class="eyebrow">PAINEL DE ESTRUTURAS</div><h3>${safe(a.description)}</h3><p>Esta imagem integra um acervo científico aberto. Use ampliação, explore sua fonte e selecione um tema.</p>${state.atlasLabels?`<div class="inspector-label"><strong>Autor/crédito</strong><span>${safe(a.creator)}</span></div><div class="inspector-label"><strong>Licença</strong><span>${safe(a.license)}</span></div>`:''}${sourceLink(state.atlas,'Ver arquivo original')}${btn('Exercitar identificação','atlas-quiz',{cls:'btn-primary',icon:'target'})}</div></div><div class="atlas-gallery">${assets.map(([key,a])=>`<button class="gallery-item ${state.atlas===key?'active':''}" data-action="set-atlas" data-key="${key}">${scienceImage(key,{onClick:false})}<span>${safe(a.description)}</span></button>`).join('')}</div><p class="caption-note">As imagens anatômicas são produzidas por autores humanos e não foram geradas por IA. A disponibilidade depende da conexão ao Wikimedia Commons. Hotspots não são sobrepostos quando não há validação de coordenadas na imagem.</p>`;}
function simSvg(ex){let special=['ventilate','hematosis','oxygen','heartbeat','electric','flow','glycemia'].includes(ex.key);let m=mod(ex.module);const stage=Math.min(state.labStep,m.steps.length-1);if(ex.key==='ventilate'){return `<div class="sim-lung"><svg viewBox="0 0 480 290" role="img" aria-label="Modelo conceitual de ventilação pulmonar"><defs><linearGradient id="lp" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fb9faa"/><stop offset="1" stop-color="#921a35"/></linearGradient></defs><path d="M240 28v72M240 96q-22 15-70 60M240 96q22 15 70 60" fill="none" stroke="#ff8392" stroke-width="14" stroke-linecap="round"/><path class="lung-l" d="M217 88Q135 62 91 136T81 259Q147 277 219 244Z" fill="url(#lp)" opacity=".80" stroke="#fbb4bc" stroke-width="2"/><path class="lung-r" d="M263 88Q345 62 389 136T399 259Q333 277 261 244Z" fill="url(#lp)" opacity=".80" stroke="#fbb4bc" stroke-width="2"/><path class="diaphragm" d="M72 254Q240 199 408 254" stroke="#ffb2c5" stroke-width="8" fill="none" stroke-linecap="round"/><text x="240" y="17" text-anchor="middle">TRAQUEIA</text><text x="240" y="286" text-anchor="middle">DIAFRAGMA</text></svg><div class="sim-breathe-info">${stage<3?'FASE INSPIRATÓRIA':'FASE EXPIRATÓRIA'}</div></div>`;}
if(ex.key==='hematosis'||ex.key==='oxygen'){return `<svg class="gas-diagram" viewBox="0 0 650 270" role="img" aria-label="Modelo de alvéolo e capilar"><ellipse cx="245" cy="133" rx="128" ry="105" stroke="#efa2ab" stroke-width="5" fill="#6d2434"/><path d="M410 57Q540 15 545 120T430 224" stroke="#d9678b" stroke-width="32" stroke-linecap="round" fill="none" opacity=".7"/><path d="M330 108h110m-20-8 20 8-20 8" class="oxygen-arrow" fill="none" stroke="#9bdcea" stroke-width="5"/><path d="M440 160H330m20-8-20 8 20 8" class="carbon-arrow" fill="none" stroke="#ffc07e" stroke-width="5"/><text x="245" y="133" text-anchor="middle" font-size="19">ALVÉOLO</text><text x="512" y="258" text-anchor="middle">CAPILAR</text><text x="383" y="85" text-anchor="middle" fill="#9bdcea">O₂ →</text><text x="383" y="189" text-anchor="middle" fill="#ffc07e">← CO₂</text></svg>`;}
if(ex.key==='glycemia'){let meal=state.labParam==='refeicao';let pts=meal?'0,138 80,121 155,54 220,72 295,100 370,119 470,137':'0,59 75,77 145,101 220,119 290,102 370,88 470,91';return `<div class="sim-graph"><div class="graph-kicker">TENDÊNCIA ILUSTRATIVA DE GLICOSE — ${meal?'APÓS REFEIÇÃO':'ENTRE REFEIÇÕES'}</div><svg viewBox="0 0 520 205" role="img" aria-label="Curva conceitual da glicemia"><path d="M22 22v160h476" stroke="#87636b" fill="none" stroke-width="2"/><path d="M22 105H498" stroke="#78404e" stroke-dasharray="6 6"/><polyline points="${pts.split(' ').map(pt=>{let [x,y]=pt.split(',').map(Number);return `${x+23},${y+21}`}).join(' ')}" fill="none" stroke="#fb748d" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/><text x="28" y="18">Glicose (qualitativo)</text><text x="490" y="198" text-anchor="end">Tempo →</text></svg><small>${meal?'Insulina tende a aumentar; o fígado e os tecidos captam ou armazenam glicose.':'Glucagon favorece disponibilidade hepática de glicose.'}</small></div>`;}
if(ex.key==='heartbeat'||ex.key==='electric'){return `<div class="heart-simulator"><span class="heart-shape ${state.labRunning?'beating':''}">${I('heart',150)}</span><div class="heart-meter"><span>Fase ${stage+1}/${m.steps.length}</span><svg viewBox="0 0 450 90"><path d="M5 52H75l10-12 11 39 14-70 16 43H218l10-11 10 37 11-69 16 44H445" stroke="#f27888" fill="none" stroke-width="3" stroke-linejoin="round"/></svg><small>Representação conceitual · não é um ECG diagnóstico</small></div></div>`;}
if(ex.key==='flow'){let radius=state.labParam==='amplo'?23:state.labParam==='estreito'?9:16;return `<div class="sim-flow"><svg viewBox="0 0 650 250" role="img" aria-label="Diagrama de vasos e fluxo"><path d="M20 ${125-radius}H630V${125+radius}H20Z" fill="#791c31" stroke="#e88da0" stroke-width="2"/><g class="flow-particles">${[70,135,200,265,330,395,460,525].map(x=>`<circle cx="${x}" cy="125" r="6" fill="#ffb2bd"/>`).join('')}</g><text x="325" y="210" text-anchor="middle">Raio relativo: ${radius} · maior raio reduz resistência no modelo ideal</text></svg></div>`;}
return `<div class="sim-process">${m.steps.slice(0,7).map((s,i)=>`<div class="sim-node ${i===stage?'current':''} ${i<stage?'passed':''}"><span>${i<stage?I('check',18):String(i+1).padStart(2,'0')}</span><p>${safe(s.split(':')[0].split(';')[0].slice(0,55))}</p></div>${i<m.steps.length-1?`<span class="sim-connector">${I('arrow',14)}</span>`:''}`).join('')}</div>`;}
function lab(){let ex=labExperiments[state.lab],m=mod(ex.module),last=m.steps.length;return `${sectionTitle('PESQUISA EXPERIMENTAL','Laboratório de fisiologia','Modelos conceituais interativos com explicações científicas e controles de reprodução.')}<div class="lab-layout"><aside class="lab-menu">${labExperiments.map((e,i)=>`<button class="lab-item ${i===state.lab?'active':''}" data-action="choose-lab" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${safe(e.title)}</b><small>${safe(mod(e.module).name)}</small></div>${I('chevron',15)}</button>`).join('')}</aside><div class="lab-main"><div class="lab-top"><span class="eyebrow">EXPERIMENTO ${String(state.lab+1).padStart(2,'0')} / ${labExperiments.length}</span><h2>${safe(ex.title)}</h2><p>${safe(m.focus)}</p></div><div class="simulation-stage ${state.labRunning?'running':''}" style="--speed:${Math.round(1/state.labSpeed*1800)}ms">${simSvg(ex)}</div><div class="experiment-controls"><div class="control-group"><button class="play-main" data-action="lab-play">${I(state.labRunning?'pause':'play',20)} ${state.labRunning?'Pausar':'Iniciar'}</button><button data-action="lab-prev" aria-label="Etapa anterior">${I('chevron',16)}<span class="flip-h">${I('chevron',16)}</span></button><button data-action="lab-next">Próxima etapa ${I('arrow',16)}</button><button data-action="lab-restart">${I('reset',17)} Reiniciar</button></div><div class="control-group"><label for="lab-speed">Velocidade</label><select id="lab-speed" data-control="lab-speed"><option value="0.5" ${state.labSpeed===.5?'selected':''}>0,5×</option><option value="1" ${state.labSpeed===1?'selected':''}>1×</option><option value="2" ${state.labSpeed===2?'selected':''}>2×</option></select></div></div><div class="step-slider"><div class="progress-bar"><i style="width:${(state.labStep+1)/last*100}%"></i></div><span>ETAPA ${state.labStep+1} DE ${last}</span></div><div class="experiment-explain"><span class="phase">ETAPA ATIVA · ${String(state.labStep+1).padStart(2,'0')}</span><h3>${safe(m.steps[state.labStep]||m.steps[0])}</h3><p>Observe a sequência e relacione o fenômeno aos órgãos do módulo <strong>${safe(m.name)}</strong>.</p>${(ex.key==='glycemia'||ex.key==='flow')?`<div class="scenario-select"><label for="scenario">Condição do experimento</label><select id="scenario" data-control="lab-param">${(ex.key==='glycemia'?[['normal','Entre refeições'],['refeicao','Após refeição']]:[['normal','Raio médio'],['estreito','Vaso mais estreito'],['amplo','Vaso mais amplo']]).map(([k,v])=>`<option value="${k}" ${state.labParam===k?'selected':''}>${v}</option>`).join('')}</select></div>`:''}<div class="scientific-note">${I('info',16)}<span><b>Limite do modelo:</b> ${safe(ex.note)}</span></div></div><div class="experiment-bottom">${btn('Estudar a fisiologia','navigate',{cls:'btn-outline',attrs:`data-view="modulo" data-id="${m.id}"`,icon:'book'})}${btn('Testar compreensão','lab-quiz',{icon:'target'})}</div></div></div>`;}
function stopLab(){clearInterval(labTimer);labTimer=null;state.labRunning=false;}
function runLab(){clearInterval(labTimer);if(!state.labRunning)return;labTimer=setInterval(()=>{let last=mod(labExperiments[state.lab].module).steps.length;state.labStep=(state.labStep+1)%last;render();},Math.round(2200/state.labSpeed));}
function buildPool(mId='todos',type='multipla'){let pool=modules.filter(m=>mId==='todos'||m.id===mId).flatMap(m=>m.facts.map(f=>({id:`${m.id}:${f.id}`,module:m.id,term:f.term,def:f.def})));return pool;}
function makeQuestion(base,type='multipla',difficulty='todos',style='classico'){let m=mod(base.module),others=shuffle(m.facts.filter(f=>f.term!==base.term&&clean(f.term)!==clean(base.term))).slice(0,3);let choices=shuffle([base.term,...others.map(x=>x.term)]);if(type==='vf'){let trueChoice=Math.random()>.5,shown=trueChoice?base.term:others[0].term;return {...base,type:'vf',prompt:`A descrição a seguir corresponde a “${shown}”?`,choices:['Verdadeiro','Falso'],answer:trueChoice?'Verdadeiro':'Falso',shown,why:`${base.term}: ${base.def}`};}
if(type==='lacuna'){return {...base,type:'lacuna',prompt:'Qual termo científico completa corretamente a definição?',choices,answer:base.term,why:base.def};}
if(type==='associar'){return {...base,type:'associar',prompt:'Associe a estrutura à função descrita:',choices,answer:base.term,why:base.def};}
let prompt=difficulty==='avancada'||difficulty==='especialista'?'Considere a descrição fisiológica. Qual estrutura, molécula ou processo corresponde a ela?':'Qual é o conceito descrito?';
if(style==='enem')prompt='Em uma investigação de fisiologia, o pesquisador encontra a característica descrita. Qual conceito explica melhor a observação?';
if(style==='vestibular')prompt='Assinale a alternativa que identifica corretamente a estrutura ou mecanismo apresentado no enunciado.';
if(style==='universidade')prompt='Com base na anatomia funcional e na terminologia científica, identifique a estrutura ou processo correspondente.';
if(style==='atlas')prompt='Observe a ilustração anatômica de apoio e identifique o termo relacionado à definição.';
if(style==='desafio')prompt='Desafio de reconhecimento funcional: qual conceito corresponde precisamente à afirmação?';
return {...base,type:'multipla',prompt,choices,answer:base.term,why:base.def};}
function createQuiz(exam=false,params={}){stopLab();let moduleId=state.quizStyle==='aleatorio'?'todos':(params.module??state.quizModule),qty=+state.quizQuantity,pool=buildPool(moduleId);if(!pool.length){notify('Não existem questões para esta seleção.');return;}let prioritize=pool.map(p=>({...p,weight:(progress.seen[p.id]||0)+progress.attempts.filter(a=>a.id===p.id&&a.ok).length*2})).sort((a,b)=>a.weight-b.weight||Math.random()-.5);let selected=shuffle(prioritize.slice(0,Math.min(pool.length,Math.max(qty*2,qty)))).slice(0,Math.min(qty,pool.length));const type=params.type||state.quizType;let questions=selected.map(q=>makeQuestion(q,type==='mista'?shuffle(['multipla','vf','lacuna','associar'])[0]:type,state.quizDifficulty,state.quizStyle));state.quiz={questions,answers:{},flags:{},index:0,exam,started:Date.now(),ended:false,report:null,showFeedback:false};state.quizExam=exam;state.quizAnswer=null;state.view=exam?'simulados':'treinamento';for(let q of selected){progress.seen[q.id]=(progress.seen[q.id]||0)+1;}store();render();window.scrollTo({top:0,behavior:'smooth'});}
function settingsView(exam){return `<div class="quiz-settings"><div class="settings-top">${I(exam?'list':'target',32)}<div><div class="eyebrow">${exam?'MODO PROVA DIGITAL':'CENTRAL DE TREINAMENTO'}</div><h2>${exam?'Configure seu simulado':'Crie uma sessão de exercícios'}</h2><p>Questões baseadas em ${countQuestions} fatos científicos e explicações dos módulos.</p></div></div><div class="form-grid"><label>CONTEÚDO<select id="quiz-module" data-control="quiz-module"><option value="todos" ${state.quizModule==='todos'?'selected':''}>Todos os 13 sistemas</option>${modules.map(m=>`<option value="${m.id}" ${state.quizModule===m.id?'selected':''}>${safe(m.name)}</option>`).join('')}</select></label><label>QUESTÕES<select id="quiz-quantity" data-control="quiz-quantity">${[5,10,15,20,30,45,60,90,100].map(n=>`<option value="${n}" ${state.quizQuantity===n?'selected':''}>${n} questões</option>`).join('')}</select></label><label>DIFICULDADE<select id="quiz-difficulty" data-control="quiz-difficulty">${[['todos','Mista / adaptação local'],['basica','Básica'],['intermediaria','Intermediária'],['avancada','Avançada'],['especialista','Especialista']].map(([v,l])=>`<option value="${v}" ${state.quizDifficulty===v?'selected':''}>${l}</option>`).join('')}</select></label><label>TIPO DE PERGUNTA<select id="quiz-type" data-control="quiz-type">${[['multipla','Múltipla escolha'],['vf','Verdadeiro ou falso'],['lacuna','Completar lacuna'],['associar','Associação'],['mista','Formatos misturados']].map(([v,l])=>`<option value="${v}" ${state.quizType===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="quiz-advanced"><label>ESTILO DA SESSÃO<select id="quiz-style" data-control="quiz-style">${[['classico','Clássico — conceitos'],['enem','Contextual (inspirado em ENEM)'],['vestibular','Vestibular — terminologia'],['universidade','Universidade — linguagem técnica'],['atlas','Atlas — imagem de apoio'],['desafio','Desafio — identificação precisa'],['aleatorio','Aleatório total — todos os módulos']].map(([v,l])=>`<option value="${v}" ${state.quizStyle===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="timer-toggle"><input type="checkbox" id="quiz-timer" data-control="quiz-timer" ${state.quizTimer?'checked':''}> Exibir cronômetro durante a sessão</label></div><div class="quiz-mode-strip">${I('info',16)} ${exam?'Na prova, as respostas corretas aparecem apenas após a entrega. Você pode navegar e sinalizar questões para revisão.':'No treino, você recebe correção imediata e links para revisar a aula.'}</div><div class="start-row">${btn(exam?'Iniciar simulado':'Gerar questões aleatórias','start-quiz',{icon:'play',attrs:`data-exam="${exam?1:0}"`})}<span>${state.quizModule==='todos'?countQuestions:mod(state.quizModule).facts.length} questões-base disponíveis na seleção</span></div></div><div class="tips-grid"><div>${I('book',22)}<b>Base transparente</b><span>Cada questão aponta para o conceito explicado na aula.</span></div><div>${I('reset',22)}<b>Repetição inteligente</b><span>O sorteio tenta priorizar conceitos ainda pouco respondidos.</span></div><div>${I('chart',22)}<b>Evolução registrada</b><span>Resultado e respostas permanecem salvos no navegador.</span></div></div>`;}
function questionView(exam){let quiz=state.quiz,q=quiz.questions[quiz.index],n=quiz.questions.length,answer=quiz.answers[quiz.index],revealed=!exam&&answer!==undefined,marked=quiz.flags[quiz.index],elapsed=Math.floor((Date.now()-quiz.started)/1000);let correctCount=Object.values(quiz.answers).filter(x=>x!==undefined).length;return `<div class="quiz-head"><div><div class="eyebrow">${exam?'SIMULADO DIGITAL':'RECUPERAÇÃO ATIVA'}</div><h2>${exam?'Sua prova em andamento':'Treinamento científico'}</h2></div><div class="quiz-clock" ${state.quizTimer?'':'hidden'}>${I('clock',16)} <span id="quiz-clock">${Math.floor(elapsed/60).toString().padStart(2,'0')}:${(elapsed%60).toString().padStart(2,'0')}</span></div></div><div class="quiz-progress-top"><span>QUESTÃO ${quiz.index+1} / ${n}</span><span>${correctCount} respondidas</span></div><div class="progress-bar"><i style="width:${correctCount/n*100}%"></i></div><div class="quiz-body"><main class="question-panel"><div class="question-meta">${badge(mod(q.module).name)}<span>${q.type==='vf'?'VERDADEIRO OU FALSO':q.type==='associar'?'ASSOCIAÇÃO DE TERMOS':q.type==='lacuna'?'PREENCHIMENTO':'MÚLTIPLA ESCOLHA'}</span></div><h3>${safe(q.prompt)}</h3>${state.quizStyle==='atlas'?`<div class="question-visual">${scienceImage(mod(q.module).image,{cls:'quiz-anatomy-image',onClick:false})}<span>Imagem contextual geral do sistema — a região da resposta não está destacada.</span></div>`:''}<div class="question-statement">${safe(q.def)}</div><div class="options">${q.choices.map((v,i)=>`<button ${revealed?'disabled':''} class="option ${answer===v?'selected':''} ${revealed&&v===q.answer?'correct':''} ${revealed&&answer===v&&answer!==q.answer?'wrong':''}" data-action="quiz-choice" data-value="${safe(v)}"><span>${String.fromCharCode(65+i)}</span><b>${safe(v)}</b>${revealed&&v===q.answer?I('check',18):''}</button>`).join('')}</div>${revealed?`<div class="feedback ${answer===q.answer?'success':'error'}"><strong>${answer===q.answer?'Resposta correta':'Resposta incorreta'} — ${safe(q.answer)}</strong><p>${safe(q.why)}</p>${q.type!=='vf'?`<div class="option-explanations"><b>Outras alternativas:</b>${q.choices.filter(v=>v!==q.answer).map(v=>{const f=mod(q.module).facts.find(f=>f.term===v);return `<p><strong>${safe(v)}:</strong> ${safe(f?.def||'É um conceito distinto.')}</p>`;}).join('')}</div>`:`<p>A frase descreve especificamente ${safe(q.term)}, não outras estruturas do módulo.</p>`}<button data-action="feedback-lesson" data-id="${q.module}">Revisar a aula ${I('arrow',14)}</button></div>`:''}<div class="quiz-foot"><button class="btn btn-outline" data-action="quiz-back" ${quiz.index===0?'disabled':''}>Anterior</button><button class="btn btn-outline" data-action="quiz-flag">${I('star',15)} ${marked?'Remover revisão':'Marcar revisão'}</button>${quiz.index===n-1?btn(exam?'Entregar prova':'Finalizar treino','quiz-finish',{icon:'check'}):btn('Próxima questão','quiz-next',{icon:'arrow'})}</div></main><aside class="question-sidebar"><div class="eyebrow">NAVEGAÇÃO</div><div class="question-dots">${quiz.questions.map((x,i)=>`<button class="qdot ${i===quiz.index?'current':''} ${quiz.answers[i]!==undefined?'answered':''} ${quiz.flags[i]?'flagged':''}" data-action="quiz-jump" data-index="${i}">${i+1}</button>`).join('')}</div><div class="question-legend"><span><i class="legend-current"></i> Atual</span><span><i class="legend-answered"></i> Respondida</span><span><i class="legend-flag"></i> Revisar</span></div><button class="quit-btn" data-action="quiz-exit">Sair da sessão</button></aside></div>`;}
function finishQuiz(){let q=state.quiz;if(!q)return;let unanswered=q.questions.filter((_,i)=>q.answers[i]===undefined).length;if(unanswered&&!confirm(`Há ${unanswered} questão(ões) sem resposta. Deseja finalizar mesmo assim?`))return;let results=q.questions.map((x,i)=>({...x,chosen:q.answers[i]||null,ok:q.answers[i]===x.answer})),right=results.filter(x=>x.ok).length,sec=Math.round((Date.now()-q.started)/1000);for(let res of results){if(res.chosen!==null)progress.attempts.push({id:res.id,module:res.module,ok:res.ok,date:Date.now(),term:res.term});}
let report={date:Date.now(),total:q.questions.length,right,seconds:sec,mode:q.exam?'Simulado':'Treinamento',byModule:{}};for(let res of results){let x=report.byModule[res.module]||{total:0,right:0};x.total++;if(res.ok)x.right++;report.byModule[res.module]=x;}progress.exams.push(report);store();q.report={...report,results};q.ended=true;clearInterval(quizTicker);render();}
function reportView(){let q=state.quiz,r=q.report,pct=Math.round(r.right/r.total*100);let incorrect=r.results.filter(x=>!x.ok);return `<div class="report-view"><div class="report-hero"><div class="eyebrow">SESSÃO FINALIZADA · RELATÓRIO</div><h1>${q.exam?'Resultado do simulado':'Treino concluído'}</h1><p>Veja acertos, conceitos a revisar e desempenho por área.</p><div class="report-stats"><div><b>${pct}%</b><span>ACERTO</span></div><div><b>${r.right}</b><span>CORRETAS</span></div><div><b>${r.total-r.right}</b><span>INCORRETAS / EM BRANCO</span></div><div><b>${Math.floor(r.seconds/60)}m ${r.seconds%60}s</b><span>TEMPO TOTAL</span></div></div></div><div class="report-columns"><section class="article"><h3>Desempenho por sistema</h3>${Object.entries(r.byModule).map(([id,stat])=>`<div class="performance-row"><span>${safe(mod(id).name)}</span><div class="progress-bar"><i style="width:${stat.right/stat.total*100}%"></i></div><strong>${stat.right}/${stat.total}</strong></div>`).join('')}<div class="report-actions">${btn('Nova sessão','new-quiz',{icon:'reset'})}${btn('Ver evolução','navigate',{cls:'btn-outline',attrs:'data-view="evolucao"',icon:'chart'})}</div></section><section class="article"><h3>Revisão dos conceitos</h3>${incorrect.length?incorrect.slice(0,20).map(x=>`<div class="missed-term"><strong>${safe(x.term)}</strong><small>${safe(mod(x.module).name)}</small><p>${safe(x.def)}</p><button data-action="feedback-lesson" data-id="${x.module}">Revisar ${I('arrow',13)}</button></div>`).join(''):'<div class="success-message">Todos os conceitos respondidos foram acertados nesta sessão.</div>'}</section></div><section class="article all-answers"><h3>Gabarito comentado completo</h3>${r.results.map((x,i)=>`<details><summary><span class="${x.ok?'result-good':'result-bad'}">${x.ok?'✓':'×'}</span> ${i+1}. ${safe(x.term)} <small>${x.ok?'Correta':'Revisão indicada'}</small></summary><p><strong>Resposta:</strong> ${safe(x.answer)}<br><strong>Sua resposta:</strong> ${safe(x.chosen||'Em branco')}<br>${safe(x.def)}</p></details>`).join('')}</section></div>`;}
function quizView(exam=false){return state.quiz?(state.quiz.ended?reportView():questionView(exam)):settingsView(exam);}
function memory(){let m=mod(state.memoryModule),items=m.steps,idx=state.memoryIndex,assoc=(progress.associations[m.id]||{}),pao=progress.pao||[];return `${sectionTitle('MEMÓRIA ESPACIAL','Palácio Anatômico','Percorra um trajeto mental, crie associações visuais e recupere a sequência sem anotações.')}<div class="memory-layout"><aside class="memory-sidebar"><label>ESCOLHA O AMBIENTE<select id="memory-module" data-control="memory-module">${modules.map(x=>`<option value="${x.id}" ${m.id===x.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select></label><div class="memory-loci">${items.map((s,i)=>`<button class="memory-locus ${i===idx?'active':''}" data-action="memory-step" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><b>${safe(s.split(':')[0].split(';')[0].slice(0,36))}</b>${assoc[i]?I('check',14):I('chevron',14)}</button>`).join('')}</div></aside><main class="memory-main"><div class="memory-room"><div class="room-glow"></div><div class="room-number">LOCUS <span>${String(idx+1).padStart(2,'0')}</span></div><div class="room-visual">${scienceImage(m.image,{cls:'room-image',onClick:false})}</div><div class="room-title">${state.memoryReveal?safe(items[idx]):'????? — RECUPERE A ETAPA MENTALMENTE'}</div><button class="room-reveal" data-action="memory-reveal">${I('eye',16)} ${state.memoryReveal?'Ocultar informação':'Revelar informação'}</button></div><div class="memory-editor"><h3>Sua associação visual</h3><p>Imagine uma cena marcante neste ponto da jornada. Salve a descrição para recuperar a imagem mental futuramente.</p><textarea id="association" rows="3" placeholder="Ex.: uma porta com ondas que empurram o bolo alimentar...">${safe(assoc[idx]||'')}</textarea><div class="memory-buttons"><button class="btn btn-outline" data-action="save-association">${I('check',16)} Salvar associação</button><button class="btn btn-outline" data-action="memory-prev" ${idx===0?'disabled':''}>Anterior</button><button class="btn btn-primary" data-action="memory-next">${idx===items.length-1?'Voltar ao começo':'Próximo locus'} ${I('arrow',15)}</button></div><div class="recall-box"><strong>Teste de recuperação ativa</strong><p>Oculte o nome e explique mentalmente a etapa. Depois compare com a informação revelada.</p><button data-action="memory-reveal" class="text-action">${I('eye',15)} Alternar resposta</button></div></div></main></div><section class="article pao-section"><div class="section-heading"><div><div class="eyebrow">MÉTODO OPCIONAL</div><h2>Construtor PAO</h2><p>Pessoa — Ação — Objeto. Use seus próprios personagens para criar sequências.</p></div></div><div class="pao-grid"><input id="pao-person" placeholder="Pessoa" aria-label="Pessoa"><input id="pao-action" placeholder="Ação" aria-label="Ação"><input id="pao-object" placeholder="Objeto" aria-label="Objeto"><button class="btn btn-primary" data-action="save-pao">${I('plus',16)} Adicionar</button></div>${pao.length?`<div class="pao-saved">${pao.map((a,i)=>`<div><span>${i+1}</span><b>${safe(a.person)}</b><span>→ ${safe(a.action)} → ${safe(a.object)}</span><button data-action="delete-pao" data-index="${i}" aria-label="Remover associação">${I('close',14)}</button></div>`).join('')}</div>`:''}</section>`;}
function cardPool(){return modules.filter(m=>state.flashModule==='todos'||m.id===state.flashModule).flatMap(m=>m.facts.map(f=>({...f,module:m.id,key:`${m.id}:${f.id}`})));}
function flashcards(){let pool=cardPool(),idx=((state.flashIndex%pool.length)+pool.length)%pool.length,f=pool[idx],record=progress.cards[f.key]||{},due=pool.filter(f=>!(progress.cards[f.key]?.next>Date.now())).length;return `${sectionTitle('RECUPERAÇÃO ATIVA','Flashcards inteligentes','O sistema registra suas avaliações e calcula revisões futuras conforme a facilidade de lembrança.')}<div class="flash-settings"><label>FILTRAR MÓDULO<select id="flash-module" data-control="flash-module"><option value="todos">Todos os módulos</option>${modules.map(m=>`<option value="${m.id}" ${state.flashModule===m.id?'selected':''}>${safe(m.name)}</option>`).join('')}</select></label><span>${due} cartões para revisar · ${pool.length} disponíveis</span></div><div class="flashcard-area"><div class="flip-card ${state.flashFlipped?'flipped':''}" data-action="flip-card" tabindex="0" role="button" aria-label="Virar flashcard"><div class="flash-ornament">${I('heart',38)}</div><div class="eyebrow">${safe(mod(f.module).name)} • CARTÃO ${idx+1}/${pool.length}</div><div class="flash-question">${state.flashFlipped?safe(f.def):safe(f.term)}</div><span class="flash-hint">${state.flashFlipped?'VERSO • EXPLICAÇÃO':'FRENTE • CLIQUE PARA REVELAR'}</span></div><div class="flash-navigation"><button data-action="flash-prev">${I('chevron',18)} Anterior</button><button data-action="flip-card">${I('reset',16)} Virar cartão</button><button data-action="flash-next">Próximo ${I('arrow',18)}</button></div><div class="flash-grades"><span>COMO FOI SUA LEMBRANÇA?</span><div>${[['nao','Não lembrei'],['dificil','Difícil'],['lembrei','Lembrei'],['facil','Fácil']].map(([k,v])=>`<button data-action="grade-flash" data-grade="${k}" title="Agendar próxima revisão">${safe(v)}</button>`).join('')}</div>${record.next?`<small>Próxima revisão deste cartão: ${new Date(record.next).toLocaleDateString('pt-BR')}</small>`:''}</div></div><div class="scientific-note">${I('info',18)} <span>O intervalo é calculado localmente com base em um agendamento simplificado: esquecido, difícil, lembrei e fácil. Não é uma medida de inteligência.</span></div>`;}
function maps(){let groups=state.mapModule==='todos'?modules:[mod(state.mapModule)];return `${sectionTitle('MAPAS CONCEITUAIS','Conexões da vida','Explore relações entre os 13 sistemas. Selecione qualquer nó para abrir a aula.')}<div class="map-settings"><label>VISUALIZAR<select id="map-module" data-control="map-module"><option value="todos">Mapa global integrado</option>${modules.map(m=>`<option value="${m.id}" ${state.mapModule===m.id?'selected':''}>${safe(m.name)}</option>`).join('')}</select></label></div>${state.mapModule==='todos'?`<div class="global-map"><div class="map-center">${I('heart',44)}<b>HOMEOSTASE</b><span>Integração dos sistemas</span></div><div class="map-petals">${modules.map((m,i)=>`<button style="--c:${m.color}" data-action="open-module" data-id="${m.id}"><span>${String(i+1).padStart(2,'0')}</span><b>${safe(m.name)}</b><small>${safe(m.short)}</small></button>`).join('')}</div></div>`:`<div class="map-detailed"><div class="map-root" style="--c:${groups[0].color}"><span>${I('heart',27)}</span><b>${safe(groups[0].name)}</b></div><div class="map-branches">${groups[0].relations.map((r,i)=>`<div class="map-branch"><span>${I('network',22)}</span><strong>${safe(r.split(':')[0])}</strong><p>${safe(r.split(':').slice(1).join(':'))}</p></div>`).join('')}</div><div class="map-fact-pills">${groups[0].facts.slice(0,12).map(f=>`<span title="${safe(f.def)}">${safe(f.term)}</span>`).join('')}</div></div>`}<div class="scientific-note">${I('info',17)}<span>O mapa exibe ligações conceituais, não conexões anatômicas em escala. A relação exata é explicada dentro de cada módulo.</span></div>`;}
function evolution(){let c=counts(),ex=progress.exams||[],errorMap={};for(let a of progress.attempts||[]){if(!a.ok)errorMap[a.module]=(errorMap[a.module]||0)+1;}const last=ex.slice(-12);return `${sectionTitle('SEU DESEMPENHO','Evolução do conhecimento','Estatísticas privadas armazenadas localmente neste navegador.')}<div class="evolution-cards"><div><span>MÓDULOS ESTUDADOS</span><b>${c.studied}<small>/ 13</small></b>${I('layers',26)}</div><div><span>QUESTÕES RESPONDIDAS</span><b>${c.answered}</b>${I('target',26)}</div><div><span>PRECISÃO GERAL</span><b>${c.accuracy}%</b>${I('chart',26)}</div><div><span>SESSÕES REALIZADAS</span><b>${c.exams}</b>${I('star',26)}</div></div><div class="report-columns"><section class="article"><div class="section-heading"><div><div class="eyebrow">HISTÓRICO</div><h2>Desempenho por sessão</h2></div></div>${last.length?`<div class="history-chart">${last.map((r,i)=>`<div class="chart-bar" title="${new Date(r.date).toLocaleDateString('pt-BR')} · ${Math.round(r.right/r.total*100)}%"><div style="height:${Math.max(4,Math.round(r.right/r.total*100))}%"></div><span>${i+1}</span></div>`).join('')}</div>`:'<div class="empty-state">Você ainda não realizou uma sessão. Conclua um treinamento para ver o gráfico.</div>'}</section><section class="article"><div class="section-heading"><div><div class="eyebrow">REVISÃO DIRECIONADA</div><h2>Temas a reforçar</h2></div></div>${Object.entries(errorMap).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([id,n])=>`<button class="review-topic" data-action="open-module" data-id="${id}"><span>${safe(mod(id).name)}</span><b>${n} erro(s) ${I('chevron',16)}</b></button>`).join('')||'<p class="empty-state">Quando errar um conceito em treino ou prova, ele aparecerá aqui para revisão.</p>'}</section></div><section class="article"><h3>Trilhas estudadas</h3><div class="progress-modules">${modules.map(m=>`<button data-action="open-module" data-id="${m.id}" class="progress-tile ${progress.studied[m.id]?'done':''}">${progress.studied[m.id]?I('check',15):I('book',15)} ${safe(m.name)}</button>`).join('')}</div></section>`;}
function library(){return `${sectionTitle('REFERÊNCIAS E TERMOS','Biblioteca científica','Consulte fontes confiáveis, conceitos e condições de reutilização das ilustrações.')}<div class="library-grid"><section class="article"><h3>Referências para estudo</h3>${references.map(r=>`<a class="library-link" href="${safe(r.url)}" target="_blank" rel="noopener noreferrer"><div>${I('book',18)}</div><span><b>${safe(r.title)}</b><small>${safe(r.desc)}</small></span>${I('external',15)}</a>`).join('')}</section><section class="article"><h3>Imagens e créditos</h3>${Object.values(imageAssets).map(a=>`<a class="library-link" href="${safe(a.source)}" target="_blank" rel="noopener noreferrer"><div>${I('image',17)}</div><span><b>${safe(a.description)}</b><small>${safe(a.creator)} · ${safe(a.license)}</small></span>${I('external',15)}</a>`).join('')}</section></div><section class="article"><h3>Glossário pesquisável</h3>${searchBox('library-search')}<div class="glossary-grid">${modules.flatMap(m=>m.facts.slice(0,3).map(f=>({m,f}))).map(({m,f})=>`<button data-action="open-module" data-id="${m.id}"><strong>${safe(f.term)}</strong><small>${safe(f.def)}</small></button>`).join('')}</div></section>`;}
function findMatches(query,limit=12){let words=clean(query).split(/\s+/).filter(x=>x.length>1),hits=[];if(!words.length)return [];for(let m of modules){let mScore=words.reduce((s,w)=>s+(clean(m.name+' '+m.short).includes(w)?3:0),0);if(mScore)hits.push({type:'module',m,score:mScore+1,title:m.name,desc:m.summary});for(let f of m.facts){let hay=clean(f.term+' '+f.def+' '+m.name),score=words.reduce((s,w)=>s+(clean(f.term).includes(w)?5:0)+(hay.includes(w)?1:0),0);if(score)hits.push({type:'fact',m,f,score,title:f.term,desc:f.def});}}return hits.sort((a,b)=>b.score-a.score).slice(0,limit);}
function searchResults(){let hits=findMatches(state.search,60);return `${sectionTitle('BUSCA GLOBAL','Resultados da pesquisa',`Consulta: ${state.search||'(vazia)'}`)}${searchBox('main-search')}<div class="search-result-list">${hits.length?hits.map(h=>`<button data-action="open-module" data-id="${h.m.id}"><span>${I(h.type==='module'?'layers':'book',18)}</span><div><b>${safe(h.title)}</b><small>${safe(h.m.name)} · ${safe(h.desc)}</small></div>${I('arrow',16)}</button>`).join(''):'<div class="empty-state">Nenhum termo correspondente. Tente buscar órgão, hormônio, glândula ou mecanismo fisiológico.</div>'}</div>`;}
function tutor(){let hits=state.tutorResults;return `${sectionTitle('EXPLICAÇÃO FUNDAMENTADA','Tutor de fisiologia','Tutor local: busca e organiza respostas já verificadas no conteúdo. Não há IA conectada.')}<div class="tutor-layout"><div class="tutor-main"><div class="tutor-header">${I('brain',28)}<div><b>ASSISTENTE DE ESTUDO LOCAL</b><small>Modo científico • 325 verbetes estruturados</small></div></div><div class="tutor-chat"><div class="tutor-msg tutor-msg-bot"><b>Laboratório Human Body</b><p>Pergunte sobre órgãos, conceitos ou mecanismos. Vou buscar definições no acervo científico dos 13 módulos e indicar onde aprofundar.</p></div>${state.tutorQuery?`<div class="tutor-msg tutor-msg-user">${safe(state.tutorQuery)}</div>`:''}${hits?`<div class="tutor-msg tutor-msg-bot"><b>Pesquisa no conteúdo local</b>${hits.length?hits.slice(0,4).map(h=>`<div class="tutor-result"><strong>${safe(h.title)}</strong><p>${safe(h.desc)}</p><button data-action="open-module" data-id="${h.m.id}">Estudar ${safe(h.m.name)} ${I('arrow',13)}</button></div>`).join(''):'<p>Não encontrei uma definição confiável para essa consulta dentro do material disponível. Tente usar termos específicos ou explore a Biblioteca.</p>'}</div>`:''}</div><form class="tutor-form" id="tutor-form"><input name="query" placeholder="Ex.: como o ADH age nos rins?" autocomplete="off" aria-label="Perguntar ao tutor" required><button type="submit">Consultar ${I('arrow',17)}</button></form></div><aside class="tutor-prompts"><h3>Perguntas para explorar</h3>${['Como funciona a hematose?','O que é insulina?','Qual a função do néfron?','O que faz o TSH?','Como funciona a sístole?'].map(t=>`<button data-action="tutor-prompt" data-query="${safe(t)}">${I('help',15)} ${safe(t)}</button>`).join('')}</aside></div>`;}
function render(){let view=state.view,content='';switch(view){case 'inicio':content=home();break;case 'sistemas':content=modulesView();break;case 'modulo':content=moduleView();break;case 'atlas':content=atlas();break;case 'laboratorio':content=lab();break;case 'treinamento':content=quizView(false);break;case 'simulados':content=quizView(true);break;case 'memorizacao':content=memory();break;case 'flashcards':content=flashcards();break;case 'mapas':content=maps();break;case 'evolucao':content=evolution();break;case 'biblioteca':content=library();break;case 'pesquisa':content=searchResults();break;case 'tutor':content=tutor();break;default:content=home();}let app=$('app');app.innerHTML=frame(content,view==='modulo'?'sistemas':view==='pesquisa'?'inicio':view);document.body.classList.toggle('reduce-motion',!!progress.reduceMotion);if(state.modal)renderModal();document.querySelectorAll('img[data-img]').forEach(img=>{img.addEventListener('error',()=>{let p=img.closest('.scientific-image');if(p){img.hidden=true;let f=p.querySelector('.img-fallback');if(f)f.hidden=false;}},{once:true});});if(state.labRunning&&view==='laboratorio')runLab();}
function renderModal(){let m=$('modal-root');if(!m)return;if(!state.modal){m.innerHTML='';return;}let a=imageAssets[state.modal]||imageAssets.body;m.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal-dialog" role="dialog" aria-modal="true" aria-label="Imagem anatômica ampliada" ><button class="modal-close" data-action="close-modal" aria-label="Fechar">${I('close',23)}</button><h3>${safe(a.description)}</h3>${scienceImage(state.modal,{cls:'modal-image',onClick:false})}<p>${safe(a.creator)} · ${safe(a.license)}</p>${sourceLink(state.modal,'Conferir créditos completos e licença')}</div></div>`;m.querySelector('img')?.addEventListener('error',e=>{e.target.hidden=true;m.querySelector('.img-fallback').hidden=false;});}
function go(view,id){if(view==='modulo'&&id)state.module=id;state.view=view;state.sidebarOpen=false;stopLab();if(state.quiz&&['treinamento','simulados'].includes(view)&&state.quiz.exam!==(view==='simulados'))state.quiz=null;history.replaceState(null,'',`#${view}${id?'/'+id:''}`);render();window.scrollTo({top:0,behavior:progress.reduceMotion?'instant':'smooth'});}
function setHash(){let [view,id]=location.hash.replace(/^#/,'').split('/');if(routes.includes(view)||view==='modulo'||view==='pesquisa'){state.view=view;if(view==='modulo'&&modules.some(x=>x.id===id))state.module=id;}}
function eventAction(el){let a=el.dataset.action,id=el.dataset.id,val=el.dataset.value,idx=+(el.dataset.index||0);switch(a){case 'toggle-menu':state.sidebarOpen=!state.sidebarOpen;render();break;case 'toggle-motion':progress.reduceMotion=!progress.reduceMotion;store();render();break;case 'navigate':go(el.dataset.view||'inicio',el.dataset.id);break;case 'open-module':go('modulo',id);break;case 'toggle-studied':progress.studied[state.module]=!progress.studied[state.module];store();render();notify('Registro de estudo atualizado.');break;case 'train-module':state.quizModule=state.module;state.quiz=null;go('treinamento');break;case 'atlas-for-module':state.atlas=mod(state.module).image;state.atlasZoom=1;go('atlas');break;case 'atlas-quiz':state.quizModule=Object.keys(imageAssets).includes(state.atlas)?modules.find(x=>x.image===state.atlas)?.id||'todos':'todos';state.quiz=null;go('treinamento');break;case 'set-atlas':state.atlas=el.dataset.key;state.atlasZoom=1;render();break;case 'atlas-zoom-in':state.atlasZoom=Math.min(2.6,state.atlasZoom+.25);render();break;case 'atlas-zoom-out':state.atlasZoom=Math.max(.75,state.atlasZoom-.25);render();break;case 'atlas-reset':state.atlasZoom=1;render();break;case 'atlas-labels':state.atlasLabels=!state.atlasLabels;render();break;case 'image-modal':state.modal=el.dataset.key;renderModal();break;case 'close-modal':state.modal=null;renderModal();break;case 'choose-lab':stopLab();state.lab=idx;state.labStep=0;state.labParam='normal';render();break;case 'lab-for-module':{let i=labExperiments.findIndex(e=>e.module===state.module);state.lab=Math.max(0,i);state.labStep=0;go('laboratorio');break;}case 'lab-play':state.labRunning=!state.labRunning;render();break;case 'lab-next':stopLab();state.labStep=(state.labStep+1)%mod(labExperiments[state.lab].module).steps.length;render();break;case 'lab-prev':stopLab();state.labStep=Math.max(0,state.labStep-1);render();break;case 'lab-restart':stopLab();state.labStep=0;render();break;case 'lab-quiz':state.quizModule=labExperiments[state.lab].module;state.quiz=null;go('treinamento');break;case 'start-quiz':createQuiz(el.dataset.exam==='1');break;case 'quiz-choice':{let q=state.quiz;if(!q||(!q.exam&&q.answers[q.index]!==undefined))return;q.answers[q.index]=val;state.quizAnswer=val;render();break;}case 'quiz-next':state.quiz.index=Math.min(state.quiz.questions.length-1,state.quiz.index+1);render();break;case 'quiz-back':state.quiz.index=Math.max(0,state.quiz.index-1);render();break;case 'quiz-jump':state.quiz.index=idx;render();break;case 'quiz-flag':state.quiz.flags[state.quiz.index]=!state.quiz.flags[state.quiz.index];render();break;case 'quiz-finish':finishQuiz();break;case 'quiz-exit':if(confirm('Sair da sessão sem registrar o resultado?')){state.quiz=null;render();}break;case 'feedback-lesson':go('modulo',id);break;case 'new-quiz':state.quiz=null;render();break;case 'memory-for-module':state.memoryModule=state.module;state.memoryIndex=0;go('memorizacao');break;case 'flash-for-module':state.flashModule=state.module;state.flashIndex=0;go('flashcards');break;case 'memory-step':state.memoryIndex=idx;state.memoryReveal=true;render();break;case 'memory-next':state.memoryIndex=(state.memoryIndex+1)%mod(state.memoryModule).steps.length;state.memoryReveal=true;render();break;case 'memory-prev':state.memoryIndex=Math.max(0,state.memoryIndex-1);state.memoryReveal=true;render();break;case 'memory-reveal':state.memoryReveal=!state.memoryReveal;render();break;case 'save-association':{let v=$('association')?.value||'';progress.associations[state.memoryModule]??={};progress.associations[state.memoryModule][state.memoryIndex]=v;store();render();notify('Associação salva no navegador.');break;}case 'save-pao':{let person=$('pao-person').value.trim(),action=$('pao-action').value.trim(),object=$('pao-object').value.trim();if(!person||!action||!object){notify('Preencha pessoa, ação e objeto.');break;}progress.pao.push({person,action,object});store();render();break;}case 'delete-pao':progress.pao.splice(idx,1);store();render();break;case 'flip-card':state.flashFlipped=!state.flashFlipped;render();break;case 'flash-next':state.flashIndex=(state.flashIndex+1)%cardPool().length;state.flashFlipped=false;render();break;case 'flash-prev':state.flashIndex=(state.flashIndex-1+cardPool().length)%cardPool().length;state.flashFlipped=false;render();break;case 'grade-flash':{let f=cardPool()[state.flashIndex],p=progress.cards[f.key]||{interval:0,reps:0};let factor={nao:0,dificil:1,lembrei:3,facil:5}[el.dataset.grade];let days=el.dataset.grade==='nao'?0.01:Math.max(1,Math.round((p.interval||1)*factor));progress.cards[f.key]={interval:days,next:Date.now()+days*86400000,reps:p.reps+1,grade:el.dataset.grade};store();state.flashIndex=(state.flashIndex+1)%cardPool().length;state.flashFlipped=false;render();notify('Revisão agendada.');break;}case 'tutor-prompt':state.tutorQuery=el.dataset.query;state.tutorResults=findMatches(state.tutorQuery,6);render();break;}}
window.addEventListener('click',e=>{let goEl=e.target.closest('[data-go]');if(goEl){e.preventDefault();go(goEl.dataset.go);return;}let a=e.target.closest('[data-action]');if(a){if(a.closest('.modal-dialog')&&a.dataset.action==='close-modal'){eventAction(a);return;}if(a.dataset.action==='close-modal'&&a.classList.contains('modal-backdrop')){eventAction(a);return;}e.preventDefault();eventAction(a);}});
window.addEventListener('change',e=>{let key=e.target.dataset.control,v=e.target.value;switch(key){case 'quiz-module':state.quizModule=v;break;case 'quiz-quantity':state.quizQuantity=Number(v);break;case 'quiz-difficulty':state.quizDifficulty=v;break;case 'quiz-type':state.quizType=v;break;case 'quiz-style':state.quizStyle=v;break;case 'lab-speed':state.labSpeed=+v;if(state.labRunning)runLab();break;case 'lab-param':state.labParam=v;stopLab();render();break;case 'memory-module':state.memoryModule=v;state.memoryIndex=0;state.memoryReveal=true;render();break;case 'flash-module':state.flashModule=v;state.flashIndex=0;state.flashFlipped=false;render();break;case 'map-module':state.mapModule=v;render();break;}});
window.addEventListener('input',e=>{if(e.target?.dataset?.control==='quiz-timer')state.quizTimer=e.target.checked;});
window.addEventListener('submit',e=>{if(e.target.matches('[data-searchform]')){e.preventDefault();state.search=e.target.querySelector('[name="query"]').value.trim();if(!state.search){notify('Digite um conceito para pesquisar.');return;}go('pesquisa');}else if(e.target.id==='tutor-form'){e.preventDefault();state.tutorQuery=e.target.querySelector('[name="query"]').value.trim();if(!state.tutorQuery)return;state.tutorResults=findMatches(state.tutorQuery,8);render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;renderModal();}if((e.key==='Enter'||e.key===' ')&&e.target.classList?.contains('flip-card')){e.preventDefault();eventAction({dataset:{action:'flip-card'}});}if(state.view==='flashcards'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){if(e.key==='ArrowRight')eventAction({dataset:{action:'flash-next'}});if(e.key==='ArrowLeft')eventAction({dataset:{action:'flash-prev'}});}});
window.addEventListener('hashchange',()=>{setHash();render();});
setHash();render();
console.info(`HUMAN BODY Atlas da Vida: ${modules.length} módulos e ${countQuestions} conceitos verificáveis carregados.`,modules.map(m=>[m.name,m.facts.length]));

const timerPulse=setInterval(()=>{if(!state.quiz||state.quiz.ended)return;const t=document.getElementById("quiz-clock");if(!t)return;let sec=Math.floor((Date.now()-state.quiz.started)/1000);t.textContent=String(Math.floor(sec/60)).padStart(2,"0")+":"+String(sec%60).padStart(2,"0");},1000);
